CREATE OR REPLACE FUNCTION public.rpc_accept_legal_bundle(p_client_request_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  u uuid:=auth.uid();
  v_request_id text:=btrim(coalesce(p_client_request_id,''));
  terms_row private.legal_document_versions%rowtype;
  privacy_row private.legal_document_versions%rowtype;
  existing public.account_legal_acceptance_events%rowtype;
  created public.account_legal_acceptance_events%rowtype;
begin
  if u is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if char_length(v_request_id)<16 or char_length(v_request_id)>96 or v_request_id !~ '^[A-Za-z0-9_-]+$' then
    raise exception 'INVALID_CLIENT_REQUEST_ID' using errcode='22023';
  end if;

  select * into terms_row
  from private.legal_document_versions d
  where d.document_kind='TERMS' and d.is_active
    and d.published_at<=statement_timestamp() and d.effective_at<=statement_timestamp()
    and d.retired_at is null
  for share;

  select * into privacy_row
  from private.legal_document_versions d
  where d.document_kind='PRIVACY' and d.is_active
    and d.published_at<=statement_timestamp() and d.effective_at<=statement_timestamp()
    and d.retired_at is null
  for share;

  if terms_row.id is null or privacy_row.id is null then
    raise exception 'LEGAL_DOCUMENTS_NOT_PUBLISHED' using errcode='55000';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(u::text||E'\n'||v_request_id,4412));

  select * into existing
  from public.account_legal_acceptance_events a
  where a.account_id=u and a.request_id=v_request_id;

  if found then
    if existing.terms_document_id<>terms_row.id
       or existing.terms_content_sha256<>terms_row.content_sha256
       or existing.privacy_document_id<>privacy_row.id
       or existing.privacy_content_sha256<>privacy_row.content_sha256 then
      raise exception 'LEGAL_ACCEPTANCE_REQUEST_REUSED_FOR_DIFFERENT_BUNDLE' using errcode='22023';
    end if;
    return jsonb_build_object(
      'accepted',true,'idempotentReplay',true,'acceptedAt',existing.accepted_at,
      'termsVersion',existing.terms_version_label,'termsSha256',existing.terms_content_sha256,
      'privacyVersion',existing.privacy_version_label,'privacySha256',existing.privacy_content_sha256
    );
  end if;

  insert into public.account_legal_acceptance_events(
    account_id,request_id,
    terms_document_id,terms_version_label,terms_content_sha256,
    privacy_document_id,privacy_version_label,privacy_content_sha256,
    acceptance_context
  ) values (
    u,v_request_id,
    terms_row.id,terms_row.version_label,terms_row.content_sha256,
    privacy_row.id,privacy_row.version_label,privacy_row.content_sha256,
    'ACCOUNT_TERMS_PRIVACY_ACK'
  ) returning * into created;

  perform private.audit_marketplace(
    u,'LEGAL_BUNDLE_ACCEPTED','SYSTEM',created.id,null,
    jsonb_build_object(
      'termsVersion',created.terms_version_label,'termsSha256',created.terms_content_sha256,
      'privacyVersion',created.privacy_version_label,'privacySha256',created.privacy_content_sha256
    )
  );

  return jsonb_build_object(
    'accepted',true,'idempotentReplay',false,'acceptedAt',created.accepted_at,
    'termsVersion',created.terms_version_label,'termsSha256',created.terms_content_sha256,
    'privacyVersion',created.privacy_version_label,'privacySha256',created.privacy_content_sha256
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_get_legal_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  terms_row private.legal_document_versions%rowtype;
  privacy_row private.legal_document_versions%rowtype;
  u uuid:=auth.uid();
  accepted_current boolean:=false;
begin
  select * into terms_row
  from private.legal_document_versions d
  where d.document_kind='TERMS' and d.is_active
    and d.published_at<=statement_timestamp() and d.effective_at<=statement_timestamp()
    and d.retired_at is null;

  select * into privacy_row
  from private.legal_document_versions d
  where d.document_kind='PRIVACY' and d.is_active
    and d.published_at<=statement_timestamp() and d.effective_at<=statement_timestamp()
    and d.retired_at is null;

  if terms_row.id is null or privacy_row.id is null then
    return jsonb_build_object(
      'ready',false,
      'acceptedCurrentBundle',false,
      'documents','[]'::jsonb,
      'reason','LEGAL_DOCUMENTS_NOT_PUBLISHED'
    );
  end if;

  if u is not null then
    select exists(
      select 1 from public.account_legal_acceptance_events a
      where a.account_id=u
        and a.terms_document_id=terms_row.id
        and a.terms_content_sha256=terms_row.content_sha256
        and a.privacy_document_id=privacy_row.id
        and a.privacy_content_sha256=privacy_row.content_sha256
    ) into accepted_current;
  end if;

  return jsonb_build_object(
    'ready',true,
    'acceptedCurrentBundle',accepted_current,
    'reason',null,
    'documents',jsonb_build_array(
      jsonb_build_object('kind','TERMS','version',terms_row.version_label,'sha256',terms_row.content_sha256,'url',terms_row.public_url,'publishedAt',terms_row.published_at,'effectiveAt',terms_row.effective_at),
      jsonb_build_object('kind','PRIVACY','version',privacy_row.version_label,'sha256',privacy_row.content_sha256,'url',privacy_row.public_url,'publishedAt',privacy_row.published_at,'effectiveAt',privacy_row.effective_at)
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_get_processor_map_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  u uuid:=auth.uid();
  p private.processor_map_sets%rowtype;
  active_count integer;
  technical_count integer;
  required_count integer;
  covered_count integer;
  missing jsonb;
  mapped jsonb;
begin
  if u is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  select count(*) into technical_count from private.processor_provider_inventory x;
  select count(*) into required_count from private.processor_provider_inventory x where x.active and x.required_current;
  select count(*) into active_count from private.processor_map_sets x where x.retired_at is null and x.effective_at<=statement_timestamp();

  if active_count=0 then
    return jsonb_build_object('ready',false,'reason','PROCESSOR_MAP_NOT_PUBLISHED',
      'technicalProviderCount',technical_count,'requiredCurrentProviders',required_count,'runtimeProviderGateAdmitted',false);
  end if;
  if active_count<>1 then
    return jsonb_build_object('ready',false,'reason','PROCESSOR_MAP_AMBIGUOUS',
      'technicalProviderCount',technical_count,'requiredCurrentProviders',required_count,'runtimeProviderGateAdmitted',false);
  end if;

  select * into p from private.processor_map_sets x
  where x.retired_at is null and x.effective_at<=statement_timestamp()
  order by x.effective_at desc limit 1;

  select count(*) into covered_count
  from private.processor_provider_inventory i
  where i.active and i.required_current
    and exists(select 1 from private.processor_map_entries e where e.map_id=p.id and e.provider_code=i.code);

  select coalesce(jsonb_agg(i.code order by i.code),'[]'::jsonb) into missing
  from private.processor_provider_inventory i
  where i.active and i.required_current
    and not exists(select 1 from private.processor_map_entries e where e.map_id=p.id and e.provider_code=i.code);

  if covered_count<>required_count then
    return jsonb_build_object('ready',false,'reason','PROCESSOR_MAP_INCOMPLETE','mapVersion',p.map_version,
      'technicalProviderCount',technical_count,'requiredCurrentProviders',required_count,'coveredCurrentProviders',covered_count,
      'missingProviders',missing,'runtimeProviderGateAdmitted',false);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'providerCode',e.provider_code,'providerDisplayName',i.display_name,'legalEntityName',e.legal_entity_name,
    'legalRole',e.legal_role,'purpose',e.purpose,'dataCategories',e.data_categories,'processingRegions',e.processing_regions,
    'crossBorderTransfer',e.cross_border_transfer,'transferMechanism',e.transfer_mechanism,'dpaReference',e.dpa_reference,
    'privacyNoticeUrl',e.privacy_notice_url,'retentionDeletionTerms',e.retention_deletion_terms,
    'subprocessorTerms',e.subprocessor_terms,'legalBasisReference',e.legal_basis_reference
  ) order by i.display_name),'[]'::jsonb) into mapped
  from private.processor_map_entries e
  join private.processor_provider_inventory i on i.code=e.provider_code
  where e.map_id=p.id and i.active;

  return jsonb_build_object('ready',true,'reason',null,'mapVersion',p.map_version,'effectiveAt',p.effective_at,
    'counselReference',p.counsel_reference,'technicalProviderCount',technical_count,'requiredCurrentProviders',required_count,
    'coveredCurrentProviders',covered_count,'providers',mapped,'runtimeProviderGateAdmitted',false);
end;
$function$

